/* Shared proposal validation and cent-based calculation, also used by the API. */
globalThis.ProposalModel=(()=>{
 const fail=m=>{throw Error(m)},text=(v,max=2000)=>typeof v==='string'&&v.length<=max?v.trim():fail('Texto inválido ou muito longo.'),num=(v,max=10000000)=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max?v:fail('Valor inválido.'),integer=(v,max)=>Number.isInteger(num(v,max))?v:fail('Informe um número inteiro.'),cents=v=>Math.round(num(v)*100),date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v?v:fail('Data inválida.');
 const lines=v=>text(v,6000).split('\n').map(x=>x.trim()).filter(Boolean).slice(0,24);
 function url(v){v=text(v||'',1000);if(v&&!/^https:\/\//.test(v))fail('Use um endereço HTTPS para a imagem.');return v;}
 function brand(v){return {name:text(v.name,100),headline:text(v.headline,180),subtitle:text(v.subtitle,350),email:text(v.email||'',150),phone:text(v.phone||'',80),website:text(v.website||'',180),color:/^#[0-9a-f]{6}$/i.test(v.color)?v.color:'#12bcc2',logo:url(v.logo),cover:url(v.cover),benefits:text(v.benefits||'',6000),resources:text(v.resources||'',6000),implementation:text(v.implementation||'',6000),terms:text(v.terms||'',6000),closing:text(v.closing||'',1200)};}
 function item(v){if(!['plan','module'].includes(v.kind)||!['monthly','once'].includes(v.cadence))fail('Tipo de item inválido.');const name=text(v.name,100);if(!name)fail('Informe o nome.');return {name,kind:v.kind,cadence:v.cadence,price:num(v.price),setup:v.setup===null?null:num(v.setup),description:text(v.description||'',500),features:text(v.features||'',3000),unit:text(v.unit||'unidade',50),usage:text(v.usage||'',1000),archived:!!v.archived};}
 function option(v){if(v.setupConfirmed!==true)fail('Confirme o valor negociado da implantação em cada condição.');let name=text(v.name,100);if(!name||!Array.isArray(v.items)||!v.items.length||v.items.length>20)fail('Inclua itens na condição comercial.');const items=v.items.map(x=>{let quantity=integer(x.quantity,10000);if(!quantity)fail('Quantidade deve ser maior que zero.');return {name:text(x.name,100),catalogId:text(x.catalogId||'',100),kind:x.kind==='module'?'module':'plan',cadence:x.cadence==='once'?'once':'monthly',quantity,price:num(x.price),promoPrice:num(x.promoPrice),promoMonths:integer(x.promoMonths,60),features:text(x.features||'',3000),usage:text(x.usage||'',1000)};});return {name,items,setupConfirmed:true,setup:num(v.setup),parts:Math.max(1,integer(v.parts,60)),loyalty:integer(v.loyalty,120),payment:text(v.payment,300),notes:text(v.notes||'',2000)};}
 function proposal(v){const client=text(v.client,160);if(!client)fail('Informe a empresa cliente.');let issued=date(v.issued),validUntil=date(v.validUntil);if(validUntil<issued)fail('A validade deve ser igual ou posterior à emissão.');if(!Array.isArray(v.options)||!v.options.length||v.options.length>3)fail('Inclua de uma a três condições comerciais.');if(!['draft','sent','accepted','declined','archived'].includes(v.status))fail('Status inválido.');return {client,contact:text(v.contact||'',100),email:text(v.email||'',150),phone:text(v.phone||'',80),title:text(v.title||'Proposta comercial',160),issued,validUntil,status:v.status,diagnosis:text(v.diagnosis||'',6000),brand:brand(v.brand),options:v.options.map(option),seller:text(v.seller||'',100),sellerEmail:text(v.sellerEmail||'',150)};}
 function totals(o,month=1){let recurring=0,once=0;for(const i of o.items){const n=cents(i.cadence==='monthly'&&i.promoMonths>=month?i.promoPrice:i.price)*i.quantity;if(i.cadence==='monthly')recurring+=n;else once+=n;}return {monthly:recurring/100,once:once/100,setup:cents(o.setup)/100,initial:(recurring+once+cents(o.setup))/100};}
 function periodTotal(o,months=12){let sum=cents(o.setup);for(const i of o.items){if(i.cadence==='once')sum+=cents(i.price)*i.quantity;else for(let m=1;m<=months;m++)sum+=cents(m<=i.promoMonths?i.promoPrice:i.price)*i.quantity;}return sum/100;}
 return {brand,item,proposal,option,totals,periodTotal,lines};
})();
